1|#!/usr/bin/env bun
2|
3|import { createRequire } from "node:module";
4|import * as path from "node:path";
5|import { compileCodingAgent } from "./compile-binary";
6|
7|const packageDir = path.join(import.meta.dir, "..");
8|const repoRoot = path.join(packageDir, "..", "..");
9|
10|/** Binary cross-compilation settings selected by `CROSS_TARGET`. */
11|export interface CrossBuild {
12|	readonly id: string;
13|	readonly platform: string;
14|	readonly arch: string;
15|	readonly target: Bun.Build.CompileTarget;
16|}
17|
18|/** Resolves a CROSS_TARGET value to the Bun compile target used by local binary builds. */
19|export function resolveCrossBuild(value: string | undefined): CrossBuild | null {
20|	switch (value) {
21|		case undefined:
22|		case "":
23|			return null;
24|		case "darwin-arm64":
25|			return { id: value, platform: "darwin", arch: "arm64", target: "bun-darwin-arm64" };
26|		case "darwin-x64":
27|			return { id: value, platform: "darwin", arch: "x64", target: "bun-darwin-x64" };
28|		case "linux-arm64":
29|			return { id: value, platform: "linux", arch: "arm64", target: "bun-linux-arm64" };
30|		case "linux-x64":
31|			return { id: value, platform: "linux", arch: "x64", target: "bun-linux-x64-baseline" };
32|		case "win32-x64":
33|		case "windows-x64":
34|			return { id: value, platform: "win32", arch: "x64", target: "bun-windows-x64-baseline" };
35|		case "win32-arm64":
36|		case "windows-arm64":
37|			return { id: value, platform: "win32", arch: "arm64", target: "bun-windows-arm64" };
38|		default:
39|			throw new Error(`Unsupported CROSS_TARGET: ${value}`);
40|	}
41|}
42|
43|// Transformers.js is an optional, native-heavy dependency that is never bundled
44|// into the binary; the tiny-model worker `bun install`s it into a runtime cache
45|// on first use. The `catalog:` spec cannot be resolved from inside the compiled
46|// bunfs (issue #1763), so embed the concrete installed version here for the
47|// worker to pin its runtime install against.
48|const transformersManifest: unknown = createRequire(import.meta.url)("@huggingface/transformers/package.json");
49|if (
50|	typeof transformersManifest !== "object" ||
51|	transformersManifest === null ||
52|	!("version" in transformersManifest) ||
53|	typeof transformersManifest.version !== "string"
54|) {
55|	throw new Error("@huggingface/transformers package manifest has no string version");
56|}
57|const transformersVersion = transformersManifest.version;
58|
59|async function runCommand(
60|	command: string[],
61|	env: NodeJS.ProcessEnv = Bun.env,
62|	cwd: string = packageDir,
63|): Promise<void> {
64|	const proc = Bun.spawn(command, {
65|		cwd,
66|		env,
67|		stdout: "inherit",
68|		stderr: "inherit",
69|	});
70|	const exitCode = await proc.exited;
71|	if (exitCode !== 0) {
72|		throw new Error(`Command failed with exit code ${exitCode}: ${command.join(" ")}`);
73|	}
74|}
75|
